    // 小根堆，按 curSum + nums[nextIdx] 升序排列
    auto cmp = [&nums](const pair<long , int>& a, const pair<long , int>& b) {
        return a.first + nums[a.second] > b.first + nums[b.second];
    };
    priority_queue<pair<long , int>, vector<pair<long , int>>, decltype(cmp)> pq(cmp);
​
    pair<long , int> current = {0, 0};
​
    for (int i = 1; i <= k; ++i) {
        long  sum = current.first + nums[current.second];
        cout << sum << endl;
​
        if (current.second + 1 < n) {
            // 1. 当前组合加上当前商品（形成新组合）
            pq.emplace(current.first + nums[current.second], current.second + 1);
            // 2. 当前组合保留之前和，索引后移（跳过当前商品）
            current.second += 1;
            pq.push(current);
        }
​
        current = pq.top();
        pq.pop();
    }
​
    return 0;
}
