// 自定义最小堆实现优先队列
class MinHeap {
    constructor(comparator) {
        this.heap = []; // 堆数组
        this.comparator = comparator || ((a, b) => a[0] - b[0]); // 比较函数，默认按第一个元素升序
    }
​
    // 添加元素
    push(value) {
        this.heap.push(value);
        this.bubbleUp(this.heap.length - 1); // 上浮新元素
    }
​
    // 弹出最小元素
    pop() {
        const min = this.heap[0]; // 堆顶是最小元素
        const end = this.heap.pop(); // 取出最后一个元素
        if (this.heap.length > 0) {
            this.heap[0] = end; // 将最后一个元素放到堆顶
            this.sinkDown(0); // 下沉调整
        }
        return min;
    }
​
    // 上浮操作
    bubbleUp(index) {
        const element = this.heap[index];
        while (index > 0) {
            const parentIndex = Math.floor((index - 1) / 2);
            const parent = this.heap[parentIndex];
            if (this.comparator(element, parent) >= 0) break; // 如果比父节点大，停止上浮
            this.heap[index] = parent; // 否则交换位置
            index = parentIndex;
        }
        this.heap[index] = element;
    }
​
    // 下沉操作
    sinkDown(index) {
        const element = this.heap[index];
        const length = this.heap.length;
​
        while (true) {
            let leftChildIndex = 2 * index + 1;
            let rightChildIndex = 2 * index + 2;
            let leftChild, rightChild;
            let swap = null;
​
            // 检查左子节点
            if (leftChildIndex < length) {
                leftChild = this.heap[leftChildIndex];
                if (this.comparator(leftChild, element) < 0) {
                    swap = leftChildIndex;
                }
            }
​
            // 检查右子节点
            if (rightChildIndex < length) {
                rightChild = this.heap[rightChildIndex];
                if (
                    (swap === null && this.comparator(rightChild, element) < 0) ||
                    (swap !== null && this.comparator(rightChild, leftChild) < 0)
                ) {
                    swap = rightChildIndex;
                }
            }
​
            if (swap === null) break; // 如果没有需要交换的，停止下沉
            this.heap[index] = this.heap[swap]; // 交换位置
            index = swap;
        }
        this.heap[index] = element;
    }
​
    // 返回堆大小
    size() {
        return this.heap.length;
    }
}
