function solve() {
    // 比较函数：按当前和+下一个商品价格升序排列
    const comparator = (a, b) => (a.sum + nums[a.idx]) - (b.sum + nums[b.idx]);
    const heap = new MinHeap(comparator); // 创建优先队列
​
    let current = { sum: 0, idx: 0 }; // 初始状态：和为0，考虑第一个商品
​
    for (let i = 0; i < k; i++) {
        // 计算当前最小和
        const sumVal = current.sum + nums[current.idx];
        console.log(sumVal); // 输出当前和
​
        if (current.idx + 1 < n) {
            // 情况1：包含当前商品，和增加，索引后移
            const newSum = current.sum + nums[current.idx];
            const newIdx = current.idx + 1;
            heap.push({ sum: newSum, idx: newIdx });
​
            // 情况2：不包含当前商品，和不变，索引后移
            const newSum2 = current.sum;
            const newIdx2 = current.idx + 1;
            heap.push({ sum: newSum2, idx: newIdx2 });
        }
​
        // 从堆中取出下一个最小和
        if (heap.size() > 0) {
            current = heap.pop();
        } else {
            break; // 堆为空则结束
        }
    }
}

