import (
    "bufio"
    "container/heap"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// 定义堆中的元素结构
type Item struct {
    curSum  int
    nextIdx int
}
​
// 实现 heap.Interface
type PriorityQueue []Item
​
func (pq PriorityQueue) Len() int { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool {
    return pq[i].curSum+nums[pq[i].nextIdx] < pq[j].curSum+nums[pq[j].nextIdx]
}
func (pq PriorityQueue) Swap(i, j int) { pq[i], pq[j] = pq[j], pq[i] }
​
func (pq *PriorityQueue) Push(x interface{}) {
    *pq = append(*pq, x.(Item))
}
​
func (pq *PriorityQueue) Pop() interface{} {
    old := *pq
    n := len(old)
    item := old[n-1]
    *pq = old[0 : n-1]
    return item
}
​
var nums []int
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    var n, k int
    fmt.Scanf("%d %d", &n, &k)
    line, _ := reader.ReadString('\n')
    line = strings.TrimSpace(line)
    parts := strings.Split(line, " ")
    nums = make([]int, n)
    for i := range parts {
        nums[i], _ = strconv.Atoi(parts[i])
    }
​
    sort.Ints(nums)
​
    pq := &PriorityQueue{}
    heap.Init(pq)
    heap.Push(pq, Item{0, 0})
​
    for i := 0; i < k; i++ {
        // 最小组合
        cur := heap.Pop(pq).(Item)
        sum := cur.curSum + nums[cur.nextIdx]
        fmt.Println(sum)

        if cur.nextIdx+1 < n {
            // 1. 当前组合 + 当前商品
            heap.Push(pq, Item{cur.curSum + nums[cur.nextIdx], cur.nextIdx + 1})
            // 2. 跳过当前商品（索引后移）
            heap.Push(pq, Item{cur.curSum, cur.nextIdx + 1})
        }
    }
}
